"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  DatabaseIcon as PhDatabase,
  MagicWandIcon as PhWand,
  CheckIcon as PhCheck,
  WarningCircleIcon as PhWarning,
  ArrowClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface FieldDef {
  id: string;
  label: string;
  expected: string;
  initial: string;
}

const FIELDS: FieldDef[] = [
  { id: "host", label: "Host", expected: "db.acme.com", initial: "db.acme.com" },
  { id: "port", label: "Port", expected: "5432", initial: "5433" },
  { id: "apiKey", label: "API key", expected: "sk-live-9f8a2b31", initial: "live-9f8a2b31" },
];

interface DiffResult {
  prefix: string;
  gotMid: string;
  expectedMid: string;
  suffix: string;
}

function diffStrings(expected: string, actual: string): DiffResult | null {
  if (expected === actual) return null;
  const maxPrefix = Math.min(expected.length, actual.length);
  let prefixLen = 0;
  while (prefixLen < maxPrefix && expected[prefixLen] === actual[prefixLen]) prefixLen++;
  const maxSuffix = Math.min(expected.length, actual.length) - prefixLen;
  let suffixLen = 0;
  while (suffixLen < maxSuffix && expected[expected.length - 1 - suffixLen] === actual[actual.length - 1 - suffixLen]) suffixLen++;
  return {
    prefix: expected.slice(0, prefixLen),
    gotMid: actual.slice(prefixLen, actual.length - suffixLen),
    expectedMid: expected.slice(prefixLen, expected.length - suffixLen),
    suffix: suffixLen > 0 ? expected.slice(expected.length - suffixLen) : "",
  };
}

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={12} aria-hidden />;
}
function WarningIcon() {
  return <PhWarning size={13} aria-hidden />;
}
function WandIcon() {
  return <PhWand size={12} aria-hidden />;
}
function DatabaseIcon() {
  return <PhDatabase size={14} weight="fill" aria-hidden />;
}

function initialValues(): Record<string, string> {
  return Object.fromEntries(FIELDS.map((f) => [f.id, f.initial]));
}

type CheckStatus = "idle" | "checking" | "checked";

interface RecoveryDiffProps {
  className?: string;
}

export function RecoveryDiff({ className }: RecoveryDiffProps) {
  const [values, setValues] = useState<Record<string, string>>(initialValues);
  const [status, setStatus] = useState<CheckStatus>("idle");
  const [errors, setErrors] = useState<Record<string, DiffResult>>({});
  const [checkRun, setCheckRun] = useState(0);
  const [flashId, setFlashId] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const runCheck = () => {
    setStatus("checking");
    setTimeout(
      () => {
        const nextErrors: Record<string, DiffResult> = {};
        FIELDS.forEach((field) => {
          const diff = diffStrings(field.expected, values[field.id]);
          if (diff) nextErrors[field.id] = diff;
        });
        setErrors(nextErrors);
        setStatus("checked");
        setCheckRun((n) => n + 1);
      },
      shouldReduceMotion ? 80 : 500
    );
  };

  const applyFix = (field: FieldDef) => {
    setValues((prev) => ({ ...prev, [field.id]: field.expected }));
    setErrors((prev) => {
      const next = { ...prev };
      delete next[field.id];
      return next;
    });
    setFlashId(field.id);
    setTimeout(() => setFlashId((f) => (f === field.id ? null : f)), 700);
  };

  const updateValue = (id: string, value: string) => {
    setValues((prev) => ({ ...prev, [id]: value }));
    if (status === "checked") setStatus("idle");
  };

  const reset = () => {
    setValues(initialValues());
    setErrors({});
    setStatus("idle");
    setFlashId(null);
  };

  const brokenCount = Object.keys(errors).length;
  const allGood = status === "checked" && brokenCount === 0;

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
            <DatabaseIcon />
            Connect database
          </h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset to broken example"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        <div className="mt-3 space-y-3">
          {FIELDS.map((field) => {
            const error = errors[field.id];
            const flashing = flashId === field.id;
            return (
              <div key={field.id}>
                <label className="flex flex-col gap-1">
                  <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{field.label}</span>
                  <motion.div
                    key={error ? `${field.id}-shake-${checkRun}` : `${field.id}-still`}
                    initial={{ x: 0 }}
                    animate={error && !shouldReduceMotion ? { x: [0, -4, 4, -3, 3, -1, 1, 0] } : { x: 0 }}
                    transition={{ duration: 0.45, ease: [0.36, 0.07, 0.19, 0.97] }}
                  >
                    <motion.input
                      type="text"
                      value={values[field.id]}
                      onChange={(e) => updateValue(field.id, e.target.value)}
                      spellCheck={false}
                      animate={
                        flashing && !shouldReduceMotion
                          ? { boxShadow: ["0 0 0 3px rgba(5,150,105,0.4)", "0 0 0 3px rgba(5,150,105,0)"] }
                          : { boxShadow: "0 0 0 3px rgba(5,150,105,0)" }
                      }
                      transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
                      className={`w-full rounded-lg border bg-white/60 px-3 py-2 font-mono text-sm text-slate-800 focus:outline-none dark:bg-white/5 dark:text-slate-100 ${
                        error
                          ? "border-rose-300 focus-visible:border-rose-500 dark:border-rose-500/40"
                          : "border-slate-200/70 focus-visible:border-emerald-500 dark:border-white/10"
                      }`}
                    />
                  </motion.div>
                </label>
                <AnimatePresence>
                  {error && (
                    <motion.div
                      initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                      transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                      className="overflow-hidden"
                    >
                      <div className="mt-1.5 rounded-lg border border-rose-200 bg-rose-50/70 p-2.5 dark:border-rose-500/25 dark:bg-rose-500/10">
                        <p className="flex items-center gap-1.5 text-xs font-medium text-rose-700 dark:text-rose-300">
                          <WarningIcon />
                          Doesn&apos;t match what&apos;s expected
                        </p>
                        <p className="mt-1 break-all font-mono text-xs text-slate-600 dark:text-slate-300">
                          {error.prefix}
                          <span className="rounded bg-rose-200/70 px-0.5 text-rose-700 line-through dark:bg-rose-500/25 dark:text-rose-300">
                            {error.gotMid}
                          </span>
                          <span className="rounded bg-emerald-200/70 px-0.5 text-emerald-700 dark:bg-emerald-500/25 dark:text-emerald-300">
                            {error.expectedMid}
                          </span>
                          {error.suffix}
                        </p>
                        <motion.button
                          type="button"
                          onClick={() => applyFix(field)}
                          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
                          whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
                          className="mt-2 inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-2.5 py-1 text-xs font-medium text-white shadow-sm transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                        >
                          <motion.span
                            aria-hidden
                            animate={shouldReduceMotion ? { rotate: 0 } : { rotate: [0, -15, 15, 0] }}
                            transition={{ duration: 0.5, repeat: Infinity, repeatDelay: 1.2, ease: "easeInOut" }}
                          >
                            <WandIcon />
                          </motion.span>
                          Use &ldquo;{field.expected}&rdquo;
                        </motion.button>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </div>

        <motion.button
          type="button"
          onClick={runCheck}
          disabled={status === "checking"}
          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
          whileTap={shouldReduceMotion ? undefined : { scale: 0.98 }}
          className="mt-4 inline-flex w-full items-center justify-center gap-2 rounded-lg bg-slate-900 px-4 py-2 text-sm font-medium text-white shadow-sm transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:opacity-60 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          {status === "checking" ? (
            <motion.span
              aria-hidden
              className="h-3.5 w-3.5 rounded-full border-2 border-white/30 border-t-white dark:border-slate-900/30 dark:border-t-slate-900"
              animate={shouldReduceMotion ? { rotate: 0 } : { rotate: 360 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.7, repeat: Infinity, ease: "linear" }}
            />
          ) : (
            <DatabaseIcon />
          )}
          {status === "checking" ? "Checking..." : "Connect"}
        </motion.button>

        <AnimatePresence>
          {allGood && (
            <motion.p
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
              className="mt-2.5 flex items-center gap-1.5 text-xs font-medium text-emerald-600 dark:text-emerald-400"
            >
              <span className="relative flex h-4 w-4 items-center justify-center rounded-full bg-emerald-600 text-white">
                {!shouldReduceMotion && (
                  <motion.span
                    aria-hidden
                    className="absolute inset-0 rounded-full border-2 border-emerald-400/60"
                    initial={{ scale: 0.7, opacity: 0.9 }}
                    animate={{ scale: 2, opacity: 0 }}
                    transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                  />
                )}
                <CheckIcon />
              </span>
              Connected, all {FIELDS.length} fields verified.
            </motion.p>
          )}
        </AnimatePresence>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Each failure shows exactly what differs and a one-click fix for that specific problem, not a generic retry.
      </p>
    </div>
  );
}
